    seen=[]
    def handle(request):
        seen.append(dict(request.extensions))
        return httpx.Response(200)
    with httpx.Client(transport=httpx.MockTransport(handle),timeout=9,trust_env=False) as client:
        request=client.build_request("GET","https://example.test/route",timeout=.75,extensions=extensions)
        client.send(request)
    assert seen[0]["timeout"] == explicit
    assert seen[0]["trace-tag"] == "retained"
    assert extensions == {"timeout":explicit,"trace-tag":"retained"}

def _set_timeout(self, request: Request) -> None:
    if "timeout" not in request.extensions:
        timeout = (
            self.timeout
            if isinstance(self.timeout, UseClientDefault)
            else Timeout(self.timeout)
        )
        request.extensions = dict(**request.extensions, timeout=timeout.as_dict())

def iter_bytes(self, chunk_size: int | None = None) -> typing.Iterator[bytes]:
    """
    A byte-iterator over the decoded response content.
    This allows us to handle gzip, deflate, brotli, and zstd encoded responses.
    """
    if hasattr(self, "_content"):
        chunk_size = len(self._content) if chunk_size is None else chunk_size
        for i in range(0, len(self._content), max(chunk_size, 1)):
            yield self._content[i : i + chunk_size]
    else:
        decoder = self._get_content_decoder()
        chunker = ByteChunker(chunk_size=chunk_size)
        with request_context(request=self._request):
            for raw_bytes in self.iter_raw():
                decoded = decoder.decode(raw_bytes)
                for chunk in chunker.decode(decoded):
                    yield chunk
            decoded = decoder.flush()
            for chunk in chunker.decode(decoded):
                yield chunk  # pragma: no cover
