@pytest.mark.parametrize("status",[301,302,303])
def test_request_records(status):
    seen=[]
    def handle(request):
        seen.append((request.method,request.content,dict(request.headers)))
        return httpx.Response(status,headers={"location":"[EXTERNAL]/result"}) if len(seen)==1 else httpx.Response(200)
    with httpx.Client(transport=httpx.MockTransport(handle),follow_redirects=True,trust_env=False) as client:
        response=client.post("https://example.test/submit",content=b"entity")
    assert response.status_code == 200 and len(response.history)==1
    assert seen[0][0:2] == ("POST",b"entity")
    assert seen[1][0:2] == ("GET",b"")
    assert "content-length" not in seen[1][2] and "transfer-encoding" not in seen[1][2]

def _redirect_stream(
    self, request: Request, method: str
) -> SyncByteStream | AsyncByteStream | None:
    """
    Return the body that should be used for the redirect request.
    """
    if request.method == "GET" and method != "GET":
        return None

    return request.stream

def _prepare(self, default_headers: dict[str, str]) -> None:
    for key, value in default_headers.items():
        # Ignore Transfer-Encoding if the Content-Length has been set explicitly.
        if key.lower() == "transfer-encoding" and "Content-Length" in self.headers:
            continue
        self.headers.setdefault(key, value)

    auto_headers: list[tuple[bytes, bytes]] = []

    has_host = "Host" in self.headers
    has_content_length = (
        "Content-Length" in self.headers or "Transfer-Encoding" in self.headers
    )

    if not has_host and self.url.host:
        auto_headers.append((b"Host", self.url.netloc))
    if not has_content_length and self.method in ("POST", "PUT", "PATCH"):
        auto_headers.append((b"Content-Length", b"0"))

    self.headers = Headers(auto_headers + self.headers.raw)

def _redirect_url(self, request: Request, response: Response) -> URL:
    """
    Return the URL for the redirect to follow.
    """
    location = response.headers["Location"]

    try:
        url = URL(location)
    except InvalidURL as exc:
        raise RemoteProtocolError(
            f"Invalid URL in location header: {exc}.", request=request
        ) from None

    # Handle malformed 'Location' headers that are "absolute" form, have no host.
    # See: https://github.com/encode/httpx/issues/771
    if url.scheme and not url.host:
        url = url.copy_with(host=request.url.host)

    # Facilitate relative 'Location' headers, as allowed by RFC 7231.
    # (e.g. '[EXTERNAL]/resource' instead of 'http://domain.tld/path/to/resource')
    if url.is_relative_url:
        url = request.url.join(url)

    # Attach previous fragment if needed (RFC 7231 7.1.2)
    if request.url.fragment and not url.fragment:
        url = url.copy_with(fragment=request.url.fragment)

    return url

@property
def headers(self) -> Headers:
    """
    HTTP headers to include when sending requests.
    """
    return self._headers

def update(self, headers: HeaderTypes | None = None) -> None:  # type: ignore
    headers = Headers(headers)
    for key in headers.keys():
        if key in self:
            self.pop(key)
    self._list.extend(headers._list)

@headers.setter
def headers(self, headers: HeaderTypes) -> None:
    client_headers = Headers(
        {
            b"Accept": b"*[EXTERNAL]/*",
            b"Accept-Encoding": ACCEPT_ENCODING.encode("ascii"),
            b"Connection": b"keep-alive",
            b"User-Agent": USER_AGENT.encode("ascii"),
        }
    )
    client_headers.update(headers)
    self._headers = client_headers

def __contains__(self, key: typing.Any) -> bool:
    header_key = key.lower().encode(self.encoding)
    return header_key in [key for _, key, _ in self._list]

